const DecisionEngine={
 reset(){window.__decisionRace={total:0,qualitySum:0,streak:0,best:0,auto:0,choices:new Set(),history:[]}},
 score(type,choice,auto){RiderEngine.ensure();let tac=(career.skills.tactics||52)/100,wp=P.wp/Math.max(1,cfg.wp),hydr=P.fluidDef,fuel=P.gly,finish=TOTAL-P.km,grade=gradeAt(P.km),q=.55+(tac-.5)*.48+(career.racePrep?.analysis?.035:0),fit=0;
 if(type==='climb'){if(choice==='climbAttack')fit+=(wp>.45&&grade>4)?.18:-.14;if(choice==='wheel')fit+=wp<.55?.13:.05;if(choice==='pace')fit+=wp<.28?.18:.03}
 if(type==='descent'){if(choice==='flow')fit+=.12;if(choice==='risk')fit+=(career.skills.descend>68&&career.risk>.55)?.15:-.12;if(choice==='safe')fit+=career.skills.descend<58?.12:.02}
 if(type==='bodyHyd'||type==='feed'){if(choice.includes('hydrate')||choice==='feedDrink')fit+=hydr>.009?.20:.02;if(choice.includes('Hold')||choice==='feedSkip')fit+=hydr>.013?-.22:.04}
 if(type==='bodyFuel'){if(choice==='fuelGel')fit+=(fuel<210&&finish<5)?.18:.05;if(choice==='fuelBar')fit+=(fuel<260&&finish>3)?.14:.03;if(choice==='fuelHold')fit+=fuel>245?.08:-.16}
 if(type==='finale'){if(choice==='leadout')fit+=wp>.18?.12:-.08;if(choice==='anticipate')fit+=(wp>.42&&finish>.35)?.15:-.14;if(choice==='wait')fit+=wp<.36?.10:.02}
 if(type==='relay'){if(choice==='relayPull')fit+=coopState.trust>.45&&wp>.28?.10:-.08;if(choice==='relayShort')fit+=.08;if(choice==='relaySkip')fit+=wp<.20?.08:-.06}
 let reaction=auto?.66:clamp(focusClock/Math.max(.1,window.__focusCtx?.startClock||4.2),0,1);q+=fit+(reaction-.5)*.12+(Math.random()-.5)*(.09-(tac-.5)*.04);return clamp(q,.18,1.04)},
 apply(type,choice,auto){if(!window.__decisionRace)this.reset();let q=this.score(type,choice,auto),d=window.__decisionRace;d.total++;d.qualitySum+=q;d.choices.add(choice);d.auto+=auto?1:0;d.streak=q>=.72?d.streak+1:0;d.best=Math.max(d.best,d.streak);d.history.push({type,choice,q,km:P.km});if(d.history.length>20)d.history.shift();if(decisionEffect&&Number.isFinite(decisionEffect.playerDrift))decisionEffect.playerDrift*=lerp(.84,1.17,q);if(decisionEffect&&Number.isFinite(decisionEffect.targetDrift))decisionEffect.targetDrift*=lerp(1.10,.91,q);let wpAdj=(q-.58)*cfg.wp*.0045-(auto?cfg.wp*.0015:0);P.wp=clamp(P.wp+wpAdj,0,cfg.wp);tacticalScore+=Math.round((q-.55)*10);career.decisionProfile.total=(career.decisionProfile.total||0)+1;career.decisionProfile.quality=((career.decisionProfile.quality||0)*(career.decisionProfile.total-1)+q)/career.decisionProfile.total;career.decisionProfile.auto=(career.decisionProfile.auto||0)+(auto?1:0);career.decisionProfile.bestStreak=Math.max(career.decisionProfile.bestStreak||0,d.best);return q}
};
