function setDecisionEffect(kind,seconds,data={}){decisionEffect={kind,t:seconds,...data};if(['counter','climbattack','anticipate','bridge'].includes(kind))tacticMemory.aggressive++;if(['letgo','waitBreak','surgeSave','ownpace','safeDown'].includes(kind))tacticMemory.patient++;if(['shelter','climbwheel','surgeWheel','leadout'].includes(kind))tacticMemory.wheel++;if(['frontwind','surgeFront','bottleFront'].includes(kind))tacticMemory.front++;let mx=Math.max(...Object.values(tacticMemory));aiRead=mx<2?'NEUTRA':Object.entries(tacticMemory).find(x=>x[1]===mx)[0].toUpperCase();lastDecisionLog=data.label||kind;$('msg').textContent=data.message||lastDecisionLog;if(data.target)react(data.target,kind.includes('counter')?'¡RESPONDE!':kind.includes('letgo')?'¡HUECO!':'¡REACCIÓN!',kind.includes('letgo')?'attack':'chase',2.8);reactPackAround(P.km,kind.includes('counter')||kind.includes('attack')?'¡CIERRA!':kind.includes('cross')?'¡CORTE!':'¡MUEVE!','chase',62)}
