 if(e.powerBias)P.basePower=clamp(P.basePower+e.powerBias*dt,110,560);
 if(e.follow&&e.target){P.follow=true;P.followTarget=e.target;P.targetLane=lerp(P.targetLane,e.target.lane,.16)}
 if(e.playerDrift)P.km+=e.playerDrift*dt/1000;
