 if(e.groupDrift){for(const r of rivals){let gap=Math.abs((r.km-P.km)*1000);if(gap<e.groupRadius){r.km+=e.groupDrift*dt/1000;r.state='respond';r.stateT=Math.max(r.stateT,3.2)}}}
