 let x0=18,y0=16,w=Math.min(690,C.width*.49),h=166,padL=18,padR=14,top=42,bottom=25,plotH=h-top-bottom;
 ctx.save();ctx.shadowColor='rgba(0,0,0,.38)';ctx.shadowBlur=16;ctx.fillStyle='rgba(4,10,16,.91)';ctx.beginPath();ctx.roundRect(x0,y0,w,h,16);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='rgba(135,184,214,.34)';ctx.lineWidth=1;ctx.stroke();
 ctx.fillStyle='#fff';ctx.font='900 13px system-ui';ctx.textAlign='left';ctx.fillText((stageType==='CRI'?'CRI · ':'')+routeTag.toUpperCase(),x0+14,y0+19);
 let rem=Math.max(0,TOTAL-P.km),remTxt=rem<1?Math.round(rem*1000)+' m':rem.toFixed(1)+' km';ctx.fillStyle='#ff67b4';ctx.font='900 13px system-ui';ctx.textAlign='right';ctx.fillText(P.pos+'º  ·  '+remTxt+' A META',x0+w-14,y0+19);
 ctx.fillStyle='#8ea7b8';ctx.font='800 9px system-ui';ctx.textAlign='left';ctx.fillText(Math.round(pc.gain)+' m+  ·  '+TOTAL.toFixed(1)+' km  ·  perfil real acumulado',x0+14,y0+34);
 let min=pc.min,max=pc.max,range=Math.max(35,max-min),px0=x0+padL,px1=x0+w-padR,base=y0+h-bottom;
 // subtle altitude grid
 ctx.font='700 8px system-ui';for(let j=0;j<3;j++){let yy=y0+top+j*plotH/2;ctx.strokeStyle='rgba(255,255,255,.07)';ctx.beginPath();ctx.moveTo(px0,yy);ctx.lineTo(px1,yy);ctx.stroke();let av=max-j*range/2;ctx.fillStyle='rgba(185,207,220,.58)';ctx.textAlign='left';ctx.fillText(Math.round(av)+'m',px0+2,yy-3)}
 const X=km=>px0+km/TOTAL*(px1-px0),Y=a=>base-(a-min)/range*plotH;
 // terrain fill
