 // grade-colored profile line
 ctx.lineWidth=3;for(let i=1;i<pc.pts.length;i++){let a=pc.pts[i-1],b=pc.pts[i];ctx.strokeStyle=gradeColor((a.g+b.g)/2);ctx.beginPath();ctx.moveTo(X(a.km),Y(a.alt));ctx.lineTo(X(b.km),Y(b.alt));ctx.stroke()}
 // climb labels / category blocks
 for(const c of climbs){let cx=(X(c.a)+X(c.b))/2,cy=Y(pc.pts[Math.min(pc.pts.length-1,Math.round(((c.a+c.b)/2)/TOTAL*(pc.pts.length-1)))].alt);ctx.fillStyle='rgba(255,110,84,.18)';ctx.fillRect(X(c.a),y0+top,X(c.b)-X(c.a),plotH);ctx.fillStyle='#ffd0bd';ctx.font='900 8px system-ui';ctx.textAlign='center';ctx.fillText(c.n.length>16?c.n.slice(0,15)+'…':c.n,cx,Math.max(y0+top+9,cy-8));}
 for(const d of descents){ctx.fillStyle='rgba(76,173,255,.10)';ctx.fillRect(X(d.a),y0+top,X(d.b)-X(d.a),plotH)}
