 // km ticks
 ctx.font='700 8px system-ui';ctx.fillStyle='#8199a9';for(let km=0;km<=TOTAL;km+=Math.max(2,Math.round(TOTAL/6))){ctx.textAlign='center';ctx.fillText(Math.round(km),X(km),base+14)}ctx.textAlign='right';ctx.fillText('km',px1,base+14);
