let minProgress=0;if(realElapsed>=145&&realElapsed<160)minProgress=lerp(.76,.88,(realElapsed-145)/15);else if(realElapsed>=160&&realElapsed<170)minProgress=lerp(.88,.955,(realElapsed-160)/10);else if(realElapsed>=170&&realElapsed<176)minProgress=lerp(.955,.982,(realElapsed-170)/6);else if(realElapsed>=176&&realElapsed<179)minProgress=lerp(.982,.995,(realElapsed-176)/3);else if(realElapsed>=179)minProgress=.995;
