function pwr(d){P.basePower=clamp(P.basePower+d,100,650);P.follow=false;P.followTarget=null;let rel=P.basePower/cfg.cp,cap=P.physCap||9999;if(d>0){if(P.basePower>cap+8){let why=P.fluidDef>.008?'DESHIDRATACIÓN':P.glu<82?'GLUCOSA BAJA':P.gly<180?'GLUCÓGENO BAJO':P.wp<cfg.wp*.08?'W′ AGOTADO':'FATIGA';$('msg').textContent=`↑ OBJETIVO ${Math.round(P.basePower)} W · ${why}: ahora solo puedes producir ~${Math.round(cap)} W`;}else $('msg').textContent=rel>1?'↑ POTENCIA · gastarás W′':'↑ POTENCIA · más ritmo'}else{$('msg').textContent=rel<.92?'↓ POTENCIA · recuperas W′':'↓ POTENCIA · ahorras'}}function move(d){P.targetLane=clamp(P.targetLane+d,-125,125);P.follow=false;P.followTarget=null}
