 afterRace(lr){let a=this.ensure(),load=clamp(lr?.load||50,0,130),hyd=clamp(lr?.hydr||0,0,1.4),fuel=clamp(lr?.fuel||0,0,1.4),ana=clamp((lr?.anr||0)/110,0,1),aer=clamp((lr?.aer||0)/100,0,1);a.muscleFatigue=clamp(a.muscleFatigue+load*.28+ana*18+(lr?.descStress||0)*.05,0,100);a.centralFatigue=clamp(a.centralFatigue+load*.18+ana*12+Math.max(0,(lr?.decisionAuto||0))*1.2,0,100);a.glycogen=clamp(100-fuel*58-(1-(lr?.glyEnd||300)/430)*22,8,100);a.hydration=clamp(100-hyd*48,35,100);a.stress=clamp(a.stress+10+load*.08-(lr?.score||50)*.05,0,100);a.acuteLoad=clamp(a.acuteLoad*.58+load*.62,0,130);a.strain=clamp(a.acuteLoad*(1+a.monotony/100*.65),0,180);a.adaptationReserve=clamp(a.adaptationReserve-load*.17+6,8,100);this.recalc();return a},
 afterTraining(ctx){let a=this.ensure(),load=clamp(ctx.load||50,0,120),quality=clamp(ctx.quality||.7,.1,1.1),recovery=clamp(ctx.recovery||40,0,100),fam=ctx.family||'endurance';let hard=['vo2','anaerobic','mixed','threshold','climbing','tt'].includes(fam),specific={endurance:'aerobicFitness',climbing:'aerobicFitness',vo2:'aerobicFitness',threshold:'thresholdFitness',tt:'thresholdFitness',mixed:'thresholdFitness',anaerobic:'anaerobicFitness',technique:'durability',recovery:'durability'}[fam]||'aerobicFitness';let gain=clamp(load/72*quality*(a.adaptationReserve/100),0,.95);a[specific]=clamp(a[specific]+gain*(hard?1.25:.75),35,98);if(fam==='anaerobic')a.neuromuscular=clamp(a.neuromuscular+gain*.75,35,98);if(fam==='endurance'||fam==='climbing')a.durability=clamp(a.durability+gain*.55,35,98);a.muscleFatigue=clamp(a.muscleFatigue*(.62-recovery*.0018)+load*(hard?.12:.07),0,100);a.centralFatigue=clamp(a.centralFatigue*(.68-recovery*.0015)+load*(hard?.09:.045),0,100);a.glycogen=clamp(a.glycogen+38+(career.nutritionPlan==='pro'?18:career.nutritionPlan==='carb'?10:2)-load*.10,25,100);a.hydration=clamp(a.hydration+32+(career.racePrep?.electrolytes?8:0),45,100);a.sleep=clamp(a.sleep+(career.recoveryPlan==='camp'?12:career.recoveryPlan==='physio'?7:3)+(career.weekExtras||[]).includes('sleep')*7-load*(hard?.025:.01),45,100);a.stress=clamp(a.stress-recovery*.18+load*.08,0,100);a.adaptationReserve=clamp(a.adaptationReserve+recovery*.42-load*.22,8,100);a.monotony=clamp(a.monotony*.64+(ctx.monotony||35)*.36,0,100);a.acuteLoad=clamp(a.acuteLoad*.55+load*.60,0,130);a.strain=clamp(a.acuteLoad*(1+a.monotony/100*.65),0,180);a.phase=fam==='recovery'?'RECUPERACIÓN':hard?(ctx.intensity==='push'?'SOBRECARGA':'DESARROLLO'):'BASE';this.recalc();return a},
 render(){let a=this.ensure();let set=(id,v)=>{let e=$(id);if(e)e.textContent=v},bar=(id,v,invert=false)=>{let e=$(id);if(e){let q=clamp(invert?100-v:v,0,100);e.style.width=q+'%';e.style.background=q<38?'#ff6c62':q<65?'#f0c450':'linear-gradient(90deg,#58c9f4,#77dfa9)'}};set('athReadiness',Math.round(a.readiness)+'%');set('athGlycogen',Math.round(a.glycogen)+'%');set('athHydration',Math.round(a.hydration)+'%');set('athMuscleFat',Math.round(a.muscleFatigue)+'%');set('athCentralFat',Math.round(a.centralFatigue)+'%');set('athSleep',Math.round(a.sleep)+'%');set('athDurability',Math.round(a.durability)+'/100');set('athReserve',Math.round(a.adaptationReserve)+'%');set('athAcute',Math.round(a.acuteLoad));set('athChronic',Math.round(career.chronicLoad||0));set('athMonotony',Math.round(a.monotony)+'%');set('athPhase',a.phase||'BASE');bar('athReadinessBar',a.readiness);bar('athGlycogenBar',a.glycogen);bar('athHydrationBar',a.hydration);bar('athMuscleFatBar',a.muscleFatigue,true);bar('athCentralFatBar',a.centralFatigue,true);bar('athSleepBar',a.sleep);bar('athDurabilityBar',a.durability);bar('athReserveBar',a.adaptationReserve);let status=a.readiness>82?'LISTO':a.readiness>66?'CARGA ÚTIL':a.readiness>48?'FATIGADO':'RECUPERAR';set('athStatus',status);let e=$('athExplain');if(e)e.textContent=`CP estructural ${Math.round(career.cp)} W · CP disponible ${Math.round(career.cp*this.raceFactor()*clamp(career.condition||1,.72,1.08))} W · carga aguda ${Math.round(a.acuteLoad)} · strain ${Math.round(a.strain)}. El estado es un modelo deportivo del juego, no una medición clínica.`},
