function renderProgressChart(){let c=$('riderProgressChart');if(!c)return;let x=c.getContext('2d'),d=(career.weeklySnapshots||[]).slice(-12);if(!d.length)d=[{week:Math.max(1,career.week-1),cp:career.cp,mass:career.mass,wkg:career.cp/career.mass,condition:career.condition,fatigue:career.chronicFatigue}];let W=c.width,H=c.height,pad=28;x.clearRect(0,0,W,H);x.fillStyle='#0b1821';x.fillRect(0,0,W,H);x.strokeStyle='rgba(255,255,255,.08)';x.lineWidth=1;for(let i=0;i<5;i++){let yy=pad+i*(H-2*pad)/4;x.beginPath();x.moveTo(pad,yy);x.lineTo(W-pad,yy);x.stroke()}let series=[['cp','CP'],['mass','KG'],['condition','COND'],['fatigue','FAT']];let vals={cp:d.map(v=>v.cp),mass:d.map(v=>v.mass),condition:d.map(v=>(v.condition||1)*100),fatigue:d.map(v=>v.fatigue||0)};let styles=['#f0c450','#59d7ff','#6de1a9','#ff7b91'];series.forEach(([k],si)=>{let a=vals[k],mn=Math.min(...a),mx=Math.max(...a);if(mx-mn<1){mn-=1;mx+=1}x.strokeStyle=styles[si];x.lineWidth=2.2;x.beginPath();a.forEach((v,i)=>{let xx=pad+(d.length===1?0.5:i/(d.length-1))*(W-2*pad),yy=H-pad-(v-mn)/(mx-mn)*(H-2*pad);if(i===0)x.moveTo(xx,yy);else x.lineTo(xx,yy)});x.stroke()});x.font='10px sans-serif';x.fillStyle='#8ba2b2';d.forEach((v,i)=>{if(i===0||i===d.length-1||i%2===0){let xx=pad+(d.length===1?0.5:i/(d.length-1))*(W-2*pad);x.fillText('S'+v.week,xx-8,H-8)}});x.fillStyle='#f0c450';x.fillText('CP '+Math.round(d.at(-1).cp)+'W',pad,13);x.fillStyle='#59d7ff';x.fillText('Peso '+d.at(-1).mass.toFixed(1)+'kg',pad+92,13);x.fillStyle='#6de1a9';x.fillText('Cond '+Math.round((d.at(-1).condition||1)*100)+'%',pad+202,13)}
