 rank(){let L=this.ensure(),sorted=L.riders.slice().sort((a,b)=>b.points-a.points||b.wins-a.wins||b.level-a.level),i=sorted.findIndex(x=>x.id==='me');return{pos:i+1,total:sorted.length,sorted,me:sorted[i]}},
