/* ===== V46 GRAND CAREER ENGINE ===== */
const V46Engine={
  init(){
    // Level curve: fast enough to make level a real game loop, still progressively harder.
    const oldXP=career.progression?.xp||0,oldLv=Math.max(1,career.progression?.level||1);
    LevelEngine.xpForLevel=function(l){l=Math.max(1,Math.floor(l));let x=l-1;return Math.round(82*Math.pow(x,1.08)+18*x)};
    LevelEngine.levelFromXP=function(xp){xp=Math.max(0,Number(xp)||0);let lo=1,hi=2;while(this.xpForLevel(hi)<=xp&&hi<100000){lo=hi;hi*=2}while(lo+1<hi){let m=(lo+hi)>>1;if(this.xpForLevel(m)<=xp)lo=m;else hi=m}return Math.max(1,lo)};
    if((career.progression?.curve||'')!=='v46'){
      career.progression=career.progression||{};let ob=42*(oldLv-1)*(oldLv-1)+58*(oldLv-1),on=42*oldLv*oldLv+58*oldLv,frac=clamp((oldXP-ob)/Math.max(1,on-ob),0,1),nb=LevelEngine.xpForLevel(oldLv),nn=LevelEngine.xpForLevel(oldLv+1);career.progression.xp=Math.round(nb+frac*(nn-nb));career.progression.curve='v46';career.progression.level=oldLv;
    }
    LevelEngine.trainingXP=function(load,quality,stimulus){let l=this.ensure().level,base=42+(load||0)*.58+(quality||0)*42+(stimulus||0)*28;return Math.round(base*(1+Math.min(.80,Math.log10(l+1)*.24)))};
    LevelEngine.equipmentXP=function(cost,tier){return Math.max(18,Math.round(Math.sqrt(Math.max(1,cost))*3.0+(tier||1)*15))};
    LevelEngine.foodXP=function(kind){return Math.max(10,Math.round(11+Math.sqrt(this.foodUpgradeCost(kind))*.65))};
    LevelEngine.ensure();

    // Strong, readable five-axis identity. Every axis changes a different race system.
    RiderProfileEngine.raceEffects=function(){let p=this.get(),d=x=>x-48;return{
      climbPower:clamp(1+d(p.climb)*.0058,.86,1.24),
      flatPower:clamp(1+d(p.rouleur)*.0050,.87,1.21),
      sprintPower:clamp(1+d(p.sprint)*.0090,.78,1.35),
      attackPower:clamp(1+d(p.sprint)*.0038+d(p.technique)*.0022,.90,1.24),
      fatigueCost:clamp(1-d(p.endurance)*.0055,.70,1.12),
      wpRecovery:clamp(1+d(p.endurance)*.0060,.80,1.29),
      descent:clamp(1+d(p.technique)*.0045,.88,1.19),
      decision:clamp(1+d(p.technique)*.0035,.90,1.18),
      drafting:clamp(1+d(p.rouleur)*.0024+d(p.technique)*.0020,.90,1.18)
    }};
    RiderEngine.terrainFactor=function(g){RiderProfileEngine.ensure();let e=RiderProfileEngine.raceEffects(),p=RiderProfileEngine.get(),f=1;if(stageType==='CRI')f=e.flatPower*(.96+.0008*(career.skills.tt||50));else if(g>3)f=e.climbPower;else if(g<-.8)f=e.descent;else f=e.flatPower;f*=clamp(.97+(p.endurance-48)*.0013,.93,1.08);return clamp(f,.78,1.27)};
    RiderEngine.aeroFactor=function(){let p=RiderProfileEngine.get(),height=career.identity?.height||175;return clamp(1.035-(p.rouleur-48)*.0016-(p.technique-48)*.00045+(height-175)*.00035,.91,1.065)};

    // Training facilities have visible consequences without bypassing adaptation/readiness.
    FacilityEngine.applyWeek=(function(base){return function(family){let g=base.call(this,family),coach=this.factor('coach'),lab=this.factor('lab'),str=this.factor('strength'),rec=this.factor('recovery'),tec=this.factor('technique'),q=clamp(.55+(career.athlete?.readiness||75)/100*.45,.5,1.06);if(['threshold','vo2','endurance','climbing','tt'].includes(family)){career.cp+=.05*coach*q+.05*lab*q;career.vo2+=.012*lab*q}if(['anaerobic','mixed'].includes(family)){career.wp+=18*str*q;career.p5s+=.45*str*q}if(['technique','mixed'].includes(family)){RiderEngine.adaptSkill('descend',.014*tec*q);RiderEngine.adaptSkill('tactics',.016*tec*q)}career.fresh=clamp(career.fresh+.001*rec,.25,1);return g}})(FacilityEngine.applyWeek);
  },
  rivalTraits(level,role,i){let cap=clamp(56+13.5*Math.log10(level+1),58,100),base=clamp(43+10*Math.log10(level+1)+Math.sin((i+2)*1.73)*2.4,40,cap-2),t={sprint:base,endurance:base,climb:base,rouleur:base,technique:base};let add=(k,v)=>t[k]=clamp(t[k]+v,38,cap);if(role==='climber'){add('climb',10);add('endurance',4);add('sprint',-6)}if(role==='sprinter'){add('sprint',11);add('rouleur',3);add('climb',-7)}if(role==='rouleur'){add('rouleur',10);add('endurance',5);add('technique',2)}if(role==='attacker'){add('sprint',5);add('technique',6);add('endurance',2)}return t},
  rivalTerrainFactor(r,g){let t=r.traits||this.rivalTraits(r.level||1,r.role||'rouleur',r.team||0),d=x=>x-48;if(stageType==='CRI')return clamp(1+d(t.rouleur)*.0046,.88,1.20);if(g>3)return clamp(1+d(t.climb)*.0055,.86,1.23);if(g<-.8)return clamp(1+d(t.technique)*.0038,.89,1.18);return clamp(1+d(t.rouleur)*.0046,.88,1.20)},
  rivalSprintFactor(r){let t=r.traits||{},d=(t.sprint||48)-48;return clamp(1+d*.0085,.80,1.33)},
  mechanics(){let b=BikeEngine.spec();return{mass:b.mass,cda:b.cda,crr:b.crr,eta:b.eta,grip:b.grip,control:b.control,accel:b.accel}}
};
V46Engine.init();

// Make rival specialization real too: same-level fields can still contain climbers, sprinters, rouleurs and attackers.
const _v46ResetRivals=resetRivals;resetRivals=function(){_v46ResetRivals();rivals.forEach((r,i)=>{r.traits=V46Engine.rivalTraits(r.level||1,r.role||'rouleur',i);r.descSkill=clamp((r.traits.technique||50)/100+rnd(-.04,.04),.28,.96);r.wpMax*=clamp(.92+(r.traits.endurance||50)/625,.93,1.08);r.wp=Math.min(r.wp,r.wpMax);if(stageType==='CRI')r.ttPace=(r.ttPace||r.cp*.97)*V46Engine.rivalTerrainFactor(r,0)});};

// Wheel reading is affected by rouleur + technique, not a decorative number.
chooseWheel=function(){let best=null,bestScore=1e9,cross=raceEvent.type==='crosswind',eff=RiderProfileEngine.raceEffects();for(const r of rivals){let gap=(r.km-P.km)*1000;if(gap>1.2&&gap<42){let laneGap=Math.abs(r.lane-P.lane),ideal=cross?4.2:5.8,roleBonus=(r.role==='rouleur'?5:r.role==='sprinter'?3:r.role==='attacker'?2:0),groupBonus=(r.state==='respond'||r.state==='attack')?4:0,s=(Math.abs(gap-ideal)*1.35+laneGap*.055-roleBonus-groupBonus)/eff.drafting;if(s<bestScore){bestScore=s;best=r}}}P.followTarget=best;P.follow=!!best;if(best){P.targetLane=lerp(P.targetLane,best.lane,clamp(.34+.18*(eff.decision-.9),.32,.48));wheelQuality=clamp((1-bestScore/45)*eff.drafting,.15,1);$('msg').textContent=`◎ RUEDA DE ${best.name.toUpperCase()} · ${Math.round((best.km-P.km)*1000)} m · calidad ${Math.round(wheelQuality*100)}%.`;cameraKick=2;react(best,'¡A RUEDA!','chase',1.4);sfx('wheel')}else{wheelQuality=0;$('msg').textContent='No hay rueda útil delante. Acércate a un corredor para engancharte.'}};

// Add attack-profile multiplier at the moment the smart attack is launched.
const _v46SmartAttack=smartAttack;smartAttack=function(){let was=!!P.attack;_v46SmartAttack();if(!was&&P.attack){let f=RiderProfileEngine.raceEffects().attackPower;P.attack.power*=f;P.attack.kick=(P.attack.kick||1)*clamp(.98+(f-1)*.45,.94,1.12)}};

// Patch AI target factors by wrapping AI update through a lightweight per-rival temporary CP expression.
const _v46UpdateAI=updateAI;updateAI=function(dt){for(const r of rivals){let g=gradeAt(r.km),tf=V46Engine.rivalTerrainFactor(r,g);r._v46cp=r.cp;r.cp*=tf;if(r.role==='sprinter'&&TOTAL-r.km<.9)r.cp*=V46Engine.rivalSprintFactor(r)}_v46UpdateAI(dt);for(const r of rivals){if(r._v46cp){r.cp=r._v46cp;delete r._v46cp}}};

