  renderClass(){let r=LeagueEngine.rank(),band=LevelEngine.matchBand(),txt=`${r.pos}º/${r.total}`;if($('v46AlwaysClass'))$('v46AlwaysClass').innerHTML=`TEMPORADA <b>${txt}</b> · N${LevelEngine.ensure().level}`;if($('v46SeasonPos'))$('v46SeasonPos').textContent=`TEMPORADA · ${txt}`;if($('v46SeasonPts'))$('v46SeasonPts').textContent=(r.me?.points||0)+' pts';if($('v46MatchBand'))$('v46MatchBand').textContent=`Rivales N${band.min}–${band.max}`},
  renderMechanics(){let e=$('v46Mechanics');if(!e)return;let b=V46Engine.mechanics(),vals=[['MASA BICI',b.mass.toFixed(2)+' kg'],['CdA',b.cda.toFixed(3)],['Crr',(b.crr*10000).toFixed(1)+'×10⁻⁴'],['EFICIENCIA',(b.eta*100).toFixed(1)+'%'],['CONTROL',Math.round(b.control*100)+'%']];e.innerHTML=vals.map(x=>`<div class="v46MechanicStat"><small>${x[0]}</small><b>${x[1]}</b></div>`).join('')},
  renderPower(){let e=$('v46PowerGrid');if(!e)return;let p=RiderProfileEngine.get(),eco=clamp(72+(p.endurance-48)*.32+(p.rouleur-48)*.16,65,96),aero=clamp(72+(p.rouleur-48)*.38+(p.technique-48)*.12,62,97),vals=[['5 s',Math.round(career.p5s)+' W'],['1 min',Math.round(career.p1m)+' W'],['5 min',Math.round(career.p5m)+' W'],['20 min',Math.round(career.p20m)+' W'],['ECONOMÍA',Math.round(eco)+'/100'],['POS. AERO',Math.round(aero)+'/100']];e.innerHTML=vals.map(x=>`<div><small>${x[0]}</small><b>${x[1]}</b></div>`).join('')},
  syncVitals(){if(!$('v46Vitals')||!cfg)return;let wp=clamp(P.wp/cfg.wp*100,0,100),gly=clamp(P.gly/cfg.gly*100,0,100),hyd=clamp(100-P.fluidDef/.04*100,0,100);$('v46Wp').textContent=Math.round(wp)+'%';$('v46Gly').textContent=Math.round(gly)+'%';$('v46Hyd').textContent=hyd>82?'OK':hyd>58?'BAJA':'CRÍTICA';$('v46WpBar').style.width=wp+'%';$('v46GlyBar').style.width=gly+'%';$('v46HydBar').style.width=hyd+'%';$('v46WpBar').style.background=wp<25?'#ff6c62':wp<50?'#f0c450':'#c84b9d';$('v46GlyBar').style.background=gly<35?'#ff6c62':gly<60?'#f0c450':'#f0a84e';$('v46HydBar').style.background=hyd<45?'#ff6c62':hyd<70?'#f0c450':'#59c8f2'},
