 draw(){if(!running||!P)return;let t=performance.now()/1000,w=V47WheelEngine.state(),g=gradeAt(P.km),cross=Math.abs(Math.sin(wind.angle*Math.PI/180));ctx.save();
   if(P.sprint){let a=.10+.06*Math.sin(t*18);let rg=ctx.createRadialGradient(C.width*.5,C.height*.60,C.width*.08,C.width*.5,C.height*.55,C.width*.62);rg.addColorStop(0,'rgba(255,214,82,0)');rg.addColorStop(1,`rgba(255,72,34,${a})`);ctx.fillStyle=rg;ctx.fillRect(0,0,C.width,C.height);ctx.globalAlpha=.14;ctx.strokeStyle='#ffd45a';ctx.lineWidth=2;for(let i=0;i<20;i++){let y=85+(i*47+t*360)%560,x=(i*131+t*520)%C.width;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-80-(P.speed||10)*4,y+8);ctx.stroke()}}
   else if(P.attack){let a=.055+.035*Math.sin(t*12);let rg=ctx.createRadialGradient(C.width*.5,C.height*.66,C.width*.10,C.width*.5,C.height*.60,C.width*.68);rg.addColorStop(0,'rgba(255,55,154,0)');rg.addColorStop(1,`rgba(255,43,137,${a})`);ctx.fillStyle=rg;ctx.fillRect(0,0,C.width,C.height)}
   if(w.on){let pp=roadPoint(0,P.lane);ctx.globalAlpha=.14+.09*w.quality;ctx.strokeStyle='#67dfff';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(pp.x,pp.y-28,40+12*w.quality,15+5*w.quality,0,0,Math.PI*2);ctx.stroke()}
   if(cross>.62&&Math.abs(wind.speed)>10){ctx.globalAlpha=.05+.07*cross;ctx.strokeStyle='#d7f5ff';ctx.lineWidth=1.5;let dir=Math.sin(wind.angle*Math.PI/180)>0?1:-1;for(let i=0;i<13;i++){let y=80+(i*61+t*145)%570,x=(i*177+t*310)%C.width;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+dir*65,y+18);ctx.stroke()}}
   if(g>6){ctx.globalAlpha=.035*clamp(g/9,0,1);ctx.fillStyle='#ffb164';ctx.fillRect(0,0,C.width,C.height)}
   ctx.restore()}
