   let p1=career.p1m||cfg.cp*1.6;if(requested>p1*.92)s.neuromuscular=clamp(s.neuromuscular-bioDt*(.0042+.006*Math.max(0,requested/p1-1)),.18,1);else if(requested<cfg.cp*.68)s.neuromuscular=clamp(s.neuromuscular+bioDt*.00115,.18,1);
   let a=AthleteEngine.ensure(),athNeuRaw=clamp((a.neuromuscular||60)/75,.72,1.08),wp=clamp(P.wp/Math.max(1,cfg.wp),0,1),fat=clamp(P.fat||0,0,1),hyd=clamp(P.fluidDef/.026,0,1),fuel=clamp((180-P.gly)/160,0,1),heat=clamp((P.core-37.6)/1.2,0,1),hrStress=clamp(((P.hr||cfg.hrRest)-(cfg.hrMax-12))/14,0,1);
