   if(c==='bridge'&&!(gap>12&&gap<150&&s.state!=='SOLO_FRONT'))return false;
   if(c==='counter'&&!(raceEvent.type==='attack'||raceEvent.type==='surge'||['FRONT','BREAKAWAY'].includes(s.state)))return false;
   if(c==='ignore'&&!(raceEvent.type==='attack'||raceEvent.type==='breakaway'||s.state==='PELOTON'))return false;
   if(['attack','counter','bridge','push','relayHard'].includes(c)&&(s.wp<.085||s.hyd>.030||s.gly<85))return false;
   if(['drink','drinkWheel'].includes(c)&&(P.bottleMl<150||(s.hyd<.0035&&P.core<37.65)))return false;
   if(c==='drinkWheel'&&!near&&!P.followTarget)return false;
   if(c==='gel'&&(P.gels<1||s.gly>305||finish<1050))return false;
