   if(c==='sprintHold'&&!P.sprint)return false;
   if(c==='sprintAll'&&(!P.sprint||finish>175))return false;
   if(s.state==='FINALE'&&finish<350&&['drink','drinkWheel','gel','relayHard','bridge'].includes(c))return false;
