   if(s.state==='BACK')return `COLA DEL GRUPO · ${Math.round(s.frontGap||0)} m al grupo de delante`;
   if(s.state==='CROSSWIND')return `VIENTO LATERAL · riesgo de corte · ${Math.round(Math.abs(wind.speed))} km/h`;
   if(s.state==='BREAKAWAY')return `FUGA DE ${s.size} · hueco detrás ${Math.round(s.gapBehind||0)} m · confianza ${Math.round(coopState.trust*100)}%`;
   if(s.state==='CHASE')return `PERSECUCIÓN · ${Math.round(s.frontGap||0)} m por cerrar`;
   if(s.state==='CLIMB')return `${activeClimb(P.km)?.n||'PUERTO'} · ${s.g.toFixed(1)}% · posición ${s.groupPos||1}/${s.size||1}`;
   if(s.state==='DESCENT')return `DESCENSO · técnica ${Math.round(RiderProfileEngine.get().technique)} · riesgo ${Math.round((career.risk||.4)*100)}%`;
