// Real-time fatigue recovery. Strongest when relaxed AND deeply sheltered.
const _v53UpdatePhys=updatePhys;
updatePhys=function(dt){
 _v53UpdatePhys(dt);
 let wheel=(P.follow&&P.followTarget)?clamp(wheelQuality||0,0,1):0,rel=(P.power||0)/Math.max(1,cfg.cp);
 let recovery=0;
 if(rel<.72&&!P.attack&&!P.sprint)recovery+=.00038*dt;
 if(rel<.62&&!P.attack&&!P.sprint)recovery+=.00032*dt;
 if(wheel>.55&&rel<.82)recovery+=.00042*wheel*dt;
 if(wheel>.82&&rel<.76)recovery+=.00055*wheel*dt;
 P.fat=clamp(P.fat-recovery,0,1);
 // Slightly more demanding short-race resource use, with progressive absorption still intact.
 let hard=clamp(rel-.72,0,.8);
 P.gly=clamp(P.gly-dt*(.012+.025*hard),0,cfg.gly);
 P.fluidDef=clamp(P.fluidDef+dt*(.0000035+.0000065*hard),0,.08);
};

// Always deliver 3 meaningful decisions when a focus is shown.
const _v53Options=V50DecisionFlow.options.bind(V50DecisionFlow);
V50DecisionFlow.options=function(type,s=V48RaceState.snapshot()){
 let out=_v53Options(type,s)||[];
 if(out.length<3){
   V48DecisionDirector.build();
   let ctx=s.state,pool=V48DecisionDirector.catalog.filter(a=>a.ctx===ctx);
   if(!pool.length)pool=V48DecisionDirector.catalog.filter(a=>a.ctx==='PELOTON');
   let extras=pool.filter(a=>this.valid(a,s)&&!out.some(x=>x.id===a.id)).map(a=>({...a,fit:this.suitability(a,s)})).sort((a,b)=>b.fit-a.fit);
   for(const a of extras){if(out.length>=3)break;if(out.some(x=>x.code===a.code))continue;out.push(a)}
 }
 return out.slice(0,3);
};
const _v53CanOpen=V50DecisionFlow.canOpen.bind(V50DecisionFlow);
V50DecisionFlow.canOpen=function(type,s){if(!_v53CanOpen(type,s))return false;return type==='manual'||this.options(type,s).length>=2};
